// Generate TypeScript from the ontology — our Ontology SDK.
//
// Foundry generates a typed client from the ontology so code cannot disagree
// with the schema. Ours reads object_types and emits one interface per
// registered type, so a record stops being Record<string, unknown> the moment
// somebody knows which type they are holding.
//
//   pnpm gen:ontology          write the file
//   pnpm gen:ontology --check  fail if it is stale (what CI runs)
//
// The --check mode is the point. A generated file nobody regenerates is worse
// than none: it looks authoritative and is quietly wrong.

import fs from 'node:fs'
import path from 'node:path'
import pg from 'pg'

const OUT = 'packages/types/src/ontology.generated.ts'

function connectionString() {
  if (process.env.SUPABASE_DB_URL) return process.env.SUPABASE_DB_URL
  const file = path.join(process.cwd(), '.env.local')
  if (!fs.existsSync(file)) return null
  const line = fs.readFileSync(file, 'utf8').split(/\r?\n/).find((l) => l.startsWith('SUPABASE_DB_URL='))
  if (!line) return null
  const url = new URL(line.slice('SUPABASE_DB_URL='.length).trim())
  url.searchParams.delete('sslmode')
  return url.toString()
}

const TS_TYPE = { text: 'string', number: 'number', boolean: 'boolean', date: 'string' }

const pascal = (s) => s.split(/[_\s]+/).filter(Boolean).map((w) => w[0].toUpperCase() + w.slice(1)).join('')

function emit(types) {
  const lines = [
    '// GENERATED by scripts/generate-ontology-types.mjs — do not edit.',
    '// One interface per registered object type, from its properties in the',
    '// ontology. Regenerate with `pnpm gen:ontology`; CI fails if it is stale.',
    '',
  ]

  for (const t of types) {
    const props = [...(t.properties ?? []), ...(t.computed ?? []).map((c) => ({ ...c, type: 'number', computed: true }))]
    lines.push(`/** ${t.label}${t.description ? ` — ${t.description}` : ''}`)
    lines.push(` *  ${t.kind === 'builtin' ? `Code-owned; records live in \`${t.source_table}\`.` : 'Operator-authored.'} */`)
    lines.push(`export interface ${pascal(t.api_name)} {`)
    for (const p of props) {
      const ts = TS_TYPE[p.type] ?? 'unknown'
      const optional = p.required === true ? '' : '?'
      const note = p.computed === true ? '  // computed' : ''
      lines.push(`  ${p.key}${optional}: ${ts}${note}`)
    }
    lines.push('}')
    lines.push('')
  }

  lines.push('/** Every registered object type, keyed by its api name. */')
  lines.push('export interface OntologyTypes {')
  for (const t of types) lines.push(`  ${t.api_name}: ${pascal(t.api_name)}`)
  lines.push('}')
  lines.push('')
  lines.push('export type OntologyTypeName = keyof OntologyTypes')
  lines.push('')
  return lines.join('\n')
}

const url = connectionString()
if (!url) {
  console.error('SUPABASE_DB_URL not set (environment or .env.local).')
  process.exit(2)
}

const client = new pg.Client({ connectionString: url, ssl: { rejectUnauthorized: false } })
await client.connect()
const { rows } = await client.query(`
  SELECT api_name, label, description, kind, source_table,
         properties, computed_properties AS computed
  FROM object_types
  WHERE enabled
  ORDER BY api_name`)
await client.end()

const next = emit(rows)
const check = process.argv.includes('--check')
const current = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : ''

if (check) {
  if (current.replace(/\r\n/g, '\n') !== next) {
    console.error(`STALE: ${OUT} does not match the ontology. Run \`pnpm gen:ontology\` and commit.`)
    process.exit(1)
  }
  console.log(`${OUT} is current (${String(rows.length)} object types).`)
} else {
  fs.mkdirSync(path.dirname(OUT), { recursive: true })
  fs.writeFileSync(OUT, next)
  console.log(`wrote ${OUT} — ${String(rows.length)} object types`)
}
